  // inferir DDI, adicionar 9 ou alterar o telefone de um contato antigo.
  if(typeof v.telefone!=='string'||v.telefone.length>40||/[\x00-\x1f\x7f]/.test(v.telefone)||!/^[+\d(). -]+$/.test(v.telefone.trim())||v.telefone.includes('+')&&!/^\+[^+]+$/.test(v.telefone.trim()))throw Error('OPERACAO_TELEFONE_INVALIDO');
  const telefone=v.telefone.trim().replace(/[(). -]/g,'').replace(/^\+/,'');
  if(!v.telefone.trim().startsWith('+')&&telefone.length<12)throw Error('OPERACAO_TELEFONE_INVALIDO');
  return `whatsapp:${numero}:${validarDestinatarioWhatsAppExistente(telefone)}`;
