 async enfileirarTx(tx:PoolClient,i:IdentidadeOperacao,p:PedidoEnvioOperacao,autor:'humano'|'ia'|'automacao'='humano'){validarIdOperacao(p.conversaId);validarIdOperacao(p.idempotencia);validarVersaoOperacao(p.versao);if(!['text','image','audio','video','sticker','document','template'].includes(p.tipo))throw Error('OPERACAO_TIPO_INVALIDO');validarTextoOperacao(p.texto??'',4096,p.tipo!=='text');if(p.anexoId)validarIdOperacao(p.anexoId);if(p.citadaId)validarIdOperacao(p.citadaId);if(p.tipo==='template'){validarTextoOperacao(p.modeloId,180);if(!Array.isArray(p.variaveis)||p.variaveis.length>20)throw Error('OPERACAO_MODELO_INVALIDO');p.variaveis.forEach(v=>validarTextoOperacao(v,32768));} await this.exigir(tx,i,'mensagens.adicionar');return this.comando(tx,i,p.idempotencia,p,async()=>{const {templateTexto,templateSnapshot,conteudo}=await this.prepararEnvioTx(tx,i,p,autor);const mensagemId=randomUUID();await tx.query('INSERT INTO atendimento_operacao.mensagem(id,conversa_id,autor,autor_id,conteudo,tipo,estado,anexo_id,citada_id,metadados) VALUES($1,$2,$3,$4,$5,$6,\'pendente\',$7,$8,$9)',[mensagemId,p.conversaId,autor,i.id,templateTexto??p.texto??'',p.tipo,p.anexoId||null,p.citadaId||null,JSON.stringify({intencaoAtualId:p.idempotencia,...autor==='humano'?{autorNome:i.nome}:{},...templateSnapshot?{template:templateSnapshot}:{}})]);await tx.query('INSERT INTO atendimento_operacao.intencao(id,conversa_id,mensagem_id,autor_id,versao_conversa,hash,conteudo) VALUES($1,$2,$3,$4,$5,$6,$7)',[p.idempotencia,p.conversaId,mensagemId,i.id,p.versao,hashOperacao(conteudo),JSON.stringify(conteudo)]);await tx.query('UPDATE atendimento_operacao.conversa SET ultima_mensagem_em=now() WHERE id=$1',[p.conversaId]);await this.auditar(tx,i,p.idempotencia,autor==='automacao'?'enfileirar_automacao':'enfileirar',p.versao);if(p.tipo==='template'&&autor==='humano')await this.auditar(tx,i,p.idempotencia,'template_utilizado',p.versao);return {id:p.idempotencia,mensagemId,estado:'pendente'}});}
