 async salvarAnexo(i:IdentidadeOperacao,p:{conversaId:string;nome:string;mime:string;base64:string;idempotencia:string}){p={...p,mime:normalizarMimeMidiaOperacao(p.mime)};validarIdOperacao(p.conversaId);validarIdOperacao(p.idempotencia);validarTextoOperacao(p.nome,160);if(/[\\/]/.test(p.nome)||!tipoMidiaOperacao(p.mime))throw Error('OPERACAO_MIDIA_RECUSADA');if(!base64MidiaValida(p.base64))throw Error('OPERACAO_MIDIA_INVALIDA');const bytes=Buffer.from(p.base64,'base64');if(bytes.length<1||bytes.length>20971520)throw Error('OPERACAO_MIDIA_GRANDE');validarBytesMidiaOperacao(tipoMidiaOperacao(p.mime)!,p.mime,bytes);const h=createHash('sha256').update(bytes).digest('hex');await this.transacao(async tx=>{await this.exigir(tx,i,'mensagens.adicionar');this.exigirEscrita(await this.conversa(tx,p.conversaId));});await mkdir(this.midia,{recursive:true,mode:0o700});let f;try{f=await open(join(this.midia,h),'wx',0o600);await f.writeFile(bytes);await f.sync();}catch(e){if(!objetoOperacao(e)||e.code!=='EEXIST')throw e;const anterior=await readFile(join(this.midia,h));if(createHash('sha256').update(anterior).digest('hex')!==h)throw Error('OPERACAO_MIDIA_CORROMPIDA');}finally{await f?.close();}if(process.platform!=='win32'){const diretorio=await open(this.midia,'r');try{await diretorio.sync();}finally{await diretorio.close();}}return this.transacao(async tx=>{await this.exigir(tx,i,'mensagens.adicionar');this.exigirEscrita(await this.conversa(tx,p.conversaId,true));return this.comando(tx,i,p.idempotencia,[p.conversaId,p.nome,p.mime,h],async()=>{await tx.query('INSERT INTO atendimento_operacao.anexo(id,conversa_id,hash,nome,mime,tamanho,autor_id) VALUES($1,$2,$3,$4,$5,$6,$7)',[p.idempotencia,p.conversaId,h,p.nome,p.mime,bytes.length,i.id]);return {id:p.idempotencia,nome:p.nome,mime:p.mime,tamanho:bytes.length,url:'/api/atendimento/operacao/anexo/'+p.idempotencia};});});}
